// Expects items shaped like:
// { customer, phone, doc_type: 'invoice'|'quote', doc_ref, amount, currency, days_silent, last_message }
// The escalation ladder: nudge on day 3, 7, 14 and 21 of silence — then stop and flag.
const LADDER = { 3: 'gentle', 7: 'friendly-firm', 14: 'direct', 21: 'final' };
const out = [];
for (const item of $input.all()) {
  const rows = Array.isArray(item.json) ? item.json : (item.json.items || [item.json]);
  for (const r of rows) {
    const tone = LADDER[r.days_silent];
    if (tone) out.push({ json: { ...r, tone, chatInput: `Compose a ${tone} follow-up for this receivable: ${JSON.stringify(r)}` } });
  }
}
return out;
